function inspectionsWithoutKey(createSql, to) {
  if (!KEY_CLAUSE.test(createSql)) return null;
  const body = createSql.replace(KEY_CLAUSE, "");
  const renamed = body.replace(/^\s*CREATE\s+TABLE\s+(IF\s+NOT\s+EXISTS\s+)?("?)inspections\2/i, `CREATE TABLE ${to}`);
  if (renamed === body) return null;
  if (/REFERENCES\s+properties/i.test(renamed)) return null;
  return renamed;
}
async function retirePropertiesTable(db, indexStatements) {
  const table = async (name) => (await db.getFirstAsync(`SELECT sql FROM sqlite_master WHERE type='table' AND name=?`, [name]))?.sql ?? null;
  const props = await table("properties");
  const insp = await table("inspections");
  const rebuilt = insp ? inspectionsWithoutKey(insp, "inspections_batch5") : null;
  if (!props && !rebuilt) return "nothing";
  let began = false;
  try {
    await db.execAsync("PRAGMA foreign_keys = OFF;");
    await db.execAsync("BEGIN;");
    began = true;
    if (props) {
      await db.execAsync(
        `INSERT INTO homes (id, address, year_built, sqft, claim_state, created_at, updated_at)
           SELECT p.id, p.address, p.year_built, p.sqft, 'unclaimed', p.created_at, CAST(strftime('%s','now') AS INTEGER) * 1000
             FROM properties p
            WHERE p.address IS NOT NULL AND p.address <> ''
         ON CONFLICT(id) DO UPDATE SET
           year_built = COALESCE(homes.year_built, excluded.year_built),
           sqft       = COALESCE(homes.sqft, excluded.sqft);`
      );
    }
    if (rebuilt) {
      await db.execAsync("DROP TABLE IF EXISTS inspections_batch5;");
      await db.execAsync(rebuilt);
      await db.execAsync("INSERT INTO inspections_batch5 SELECT * FROM inspections;");
      const before = await db.getFirstAsync("SELECT COUNT(*) AS n FROM inspections");
      const after = await db.getFirstAsync("SELECT COUNT(*) AS n FROM inspections_batch5");
      if (Number(before?.n) !== Number(after?.n)) throw new Error("row count changed");
      await db.execAsync("DROP TABLE inspections;");
      await db.execAsync("ALTER TABLE inspections_batch5 RENAME TO inspections;");
      for (const s of indexStatements) await db.execAsync(s);
    }
    const refs = await db.getFirstAsync(
      `SELECT COUNT(*) AS n FROM sqlite_master WHERE type='table' AND name <> 'properties' AND sql LIKE '%REFERENCES properties%'`
    );
    if (Number(refs?.n) > 0) throw new Error("a table still refers to properties");
    if (props) await db.execAsync("DROP TABLE properties;");
    await db.execAsync("COMMIT;");
    return "done";
  } catch (e) {
    if (began) {
      try {
        await db.execAsync("ROLLBACK;");
      } catch {
      }
    }
    console.warn("[sqlite] properties retirement failed; left as it was, tried again next launch", e);
    return "failed";
  } finally {
    try {
      await db.execAsync("PRAGMA foreign_keys = ON;");
    } catch {
    }
  }
}
